class Solution {
    public int numIdenticalPairs(int[] nums) {
        int[] count = new int[101];
        int pairs = 0;
        for (int n : nums) {
            pairs += count[n];
            count[n]++;
        }
        return pairs;
    }
}

class Solution {
    public int numIdenticalPairs(int[] nums) {
        int pairs = 0;
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) {
                if (nums[i] == nums[j]) pairs++;
            }
        }
        return pairs;
    }
}
